-- ARCHIVE schema, version 1: core entities (specification §5.1).
--
-- Conventions (ARCHITECTURE.md §6.2):
--   * identifiers are UUID v7 strings generated by the native core;
--   * timestamps are Unix epoch milliseconds (UTC);
--   * booleans are INTEGER 0/1;
--   * *_key columns hold a normalised name (trimmed, lowercase) used to forbid duplicates regardless of case;
--   * colours are design token names, never raw values, so that the palette stays the single source.
-- User content is never deleted by a cascade: workspaces and folders are RESTRICT, and documents and notes
-- carry a deleted_at column so that deletion can be reversible. Only derived data (extracted text, tag links)
-- follows its owner.

CREATE TABLE workspaces (
  id TEXT PRIMARY KEY NOT NULL,
  name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 120),
  name_key TEXT NOT NULL UNIQUE,
  description TEXT NOT NULL DEFAULT '' CHECK (length(description) <= 2000),
  color TEXT NOT NULL DEFAULT 'amber'
    CHECK (color IN ('amber', 'blue', 'cyan', 'purple', 'success', 'warning', 'danger', 'neutral')),
  icon TEXT NOT NULL DEFAULT 'folder' CHECK (length(icon) BETWEEN 1 AND 64),
  is_archived INTEGER NOT NULL DEFAULT 0 CHECK (is_archived IN (0, 1)),
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

CREATE TABLE folders (
  id TEXT PRIMARY KEY NOT NULL,
  workspace_id TEXT NOT NULL REFERENCES workspaces (id) ON DELETE RESTRICT,
  parent_id TEXT REFERENCES folders (id) ON DELETE RESTRICT,
  name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 120),
  name_key TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  CHECK (parent_id IS NULL OR parent_id <> id)
);
CREATE UNIQUE INDEX folders_unique_name ON folders (workspace_id, coalesce(parent_id, ''), name_key);
CREATE INDEX folders_parent ON folders (parent_id);

CREATE TABLE documents (
  id TEXT PRIMARY KEY NOT NULL,
  title TEXT NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 500),
  original_filename TEXT NOT NULL CHECK (length(original_filename) BETWEEN 1 AND 500),
  stored_filename TEXT NOT NULL UNIQUE,
  file_extension TEXT NOT NULL CHECK (length(file_extension) BETWEEN 1 AND 16),
  mime_type TEXT NOT NULL,
  file_size INTEGER NOT NULL CHECK (file_size >= 0),
  content_hash TEXT NOT NULL CHECK (length(content_hash) = 64),
  workspace_id TEXT REFERENCES workspaces (id) ON DELETE RESTRICT,
  folder_id TEXT REFERENCES folders (id) ON DELETE RESTRICT,
  indexing_status TEXT NOT NULL DEFAULT 'pending'
    CHECK (indexing_status IN ('pending', 'processing', 'completed', 'failed', 'needs_attention')),
  metadata_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(metadata_json)),
  is_favorite INTEGER NOT NULL DEFAULT 0 CHECK (is_favorite IN (0, 1)),
  is_archived INTEGER NOT NULL DEFAULT 0 CHECK (is_archived IN (0, 1)),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  imported_at INTEGER NOT NULL,
  last_opened_at INTEGER,
  deleted_at INTEGER
);
-- Duplicate imports are refused while a document with the same content exists (specification §5.2).
CREATE UNIQUE INDEX documents_unique_content ON documents (content_hash) WHERE deleted_at IS NULL;
CREATE INDEX documents_workspace ON documents (workspace_id, folder_id);
CREATE INDEX documents_imported_at ON documents (imported_at);
CREATE INDEX documents_updated_at ON documents (updated_at);
CREATE INDEX documents_last_opened_at ON documents (last_opened_at) WHERE last_opened_at IS NOT NULL;
CREATE INDEX documents_favorites ON documents (updated_at) WHERE is_favorite = 1;
CREATE INDEX documents_indexing_status ON documents (indexing_status);

-- Extracted text lives apart from the document row so that lists never load large texts (spec §4.2).
CREATE TABLE document_contents (
  document_id TEXT PRIMARY KEY NOT NULL REFERENCES documents (id) ON DELETE CASCADE,
  content_text TEXT NOT NULL,
  extractor TEXT NOT NULL,
  extracted_at INTEGER NOT NULL
);

CREATE TABLE notes (
  id TEXT PRIMARY KEY NOT NULL,
  title TEXT NOT NULL DEFAULT '' CHECK (length(title) <= 500),
  content TEXT NOT NULL DEFAULT '',
  content_format TEXT NOT NULL DEFAULT 'tiptap-json'
    CHECK (content_format IN ('tiptap-json', 'markdown', 'plain')),
  content_text TEXT NOT NULL DEFAULT '',
  workspace_id TEXT REFERENCES workspaces (id) ON DELETE RESTRICT,
  folder_id TEXT REFERENCES folders (id) ON DELETE RESTRICT,
  -- Incremented on every save: a save based on an older revision is rejected (spec §8.3).
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  is_favorite INTEGER NOT NULL DEFAULT 0 CHECK (is_favorite IN (0, 1)),
  is_archived INTEGER NOT NULL DEFAULT 0 CHECK (is_archived IN (0, 1)),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  last_opened_at INTEGER,
  deleted_at INTEGER
);
CREATE INDEX notes_workspace ON notes (workspace_id, folder_id);
CREATE INDEX notes_updated_at ON notes (updated_at);
CREATE INDEX notes_last_opened_at ON notes (last_opened_at) WHERE last_opened_at IS NOT NULL;
CREATE INDEX notes_favorites ON notes (updated_at) WHERE is_favorite = 1;

CREATE TABLE tags (
  id TEXT PRIMARY KEY NOT NULL,
  name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 64),
  name_key TEXT NOT NULL UNIQUE,
  color TEXT NOT NULL DEFAULT 'neutral'
    CHECK (color IN ('amber', 'blue', 'cyan', 'purple', 'success', 'warning', 'danger', 'neutral')),
  created_at INTEGER NOT NULL
);

CREATE TABLE document_tags (
  document_id TEXT NOT NULL REFERENCES documents (id) ON DELETE CASCADE,
  tag_id TEXT NOT NULL REFERENCES tags (id) ON DELETE CASCADE,
  created_at INTEGER NOT NULL,
  PRIMARY KEY (document_id, tag_id)
) WITHOUT ROWID;
CREATE INDEX document_tags_tag ON document_tags (tag_id);

CREATE TABLE note_tags (
  note_id TEXT NOT NULL REFERENCES notes (id) ON DELETE CASCADE,
  tag_id TEXT NOT NULL REFERENCES tags (id) ON DELETE CASCADE,
  created_at INTEGER NOT NULL,
  PRIMARY KEY (note_id, tag_id)
) WITHOUT ROWID;
CREATE INDEX note_tags_tag ON note_tags (tag_id);

-- Polymorphic relations between resources (spec §10.4). They cannot carry foreign keys: the services remove
-- the relations of a resource when the resource itself is purged.
CREATE TABLE relations (
  id TEXT PRIMARY KEY NOT NULL,
  source_type TEXT NOT NULL CHECK (source_type IN ('document', 'note', 'concept', 'workspace', 'tag')),
  source_id TEXT NOT NULL,
  target_type TEXT NOT NULL CHECK (target_type IN ('document', 'note', 'concept', 'workspace', 'tag')),
  target_id TEXT NOT NULL,
  relation_type TEXT NOT NULL CHECK (length(relation_type) BETWEEN 1 AND 64),
  origin TEXT NOT NULL CHECK (origin IN ('user', 'rule', 'ai')),
  status TEXT NOT NULL DEFAULT 'accepted' CHECK (status IN ('suggested', 'accepted', 'rejected')),
  confidence REAL CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 1)),
  provenance_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(provenance_json)),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  CHECK (NOT (source_type = target_type AND source_id = target_id))
);
CREATE UNIQUE INDEX relations_unique ON relations (source_type, source_id, target_type, target_id, relation_type);
CREATE INDEX relations_target ON relations (target_type, target_id);

-- Real activity history (spec §13). The description is a snapshot of the resource title at event time, so the
-- history stays readable after a rename or a deletion.
CREATE TABLE timeline_events (
  id TEXT PRIMARY KEY NOT NULL,
  event_type TEXT NOT NULL CHECK (length(event_type) BETWEEN 1 AND 64),
  entity_type TEXT NOT NULL CHECK (length(entity_type) BETWEEN 1 AND 32),
  entity_id TEXT NOT NULL,
  workspace_id TEXT,
  description TEXT NOT NULL DEFAULT '' CHECK (length(description) <= 500),
  metadata_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(metadata_json)),
  created_at INTEGER NOT NULL
);
CREATE INDEX timeline_events_created_at ON timeline_events (created_at);
CREATE INDEX timeline_events_entity ON timeline_events (entity_type, entity_id);
CREATE INDEX timeline_events_workspace ON timeline_events (workspace_id, created_at);

-- AI provider configuration (spec §14.2–14.3). secret_ref names the entry of the operating system credential
-- store; the secret itself is never stored in the database.
CREATE TABLE ai_providers (
  id TEXT PRIMARY KEY NOT NULL,
  provider TEXT NOT NULL CHECK (provider IN ('anthropic', 'openai', 'gemini')),
  display_name TEXT NOT NULL CHECK (length(trim(display_name)) BETWEEN 1 AND 120),
  model TEXT NOT NULL DEFAULT '' CHECK (length(model) <= 200),
  secret_ref TEXT CHECK (secret_ref IS NULL OR length(secret_ref) BETWEEN 1 AND 200),
  preferences_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(preferences_json)),
  is_default INTEGER NOT NULL DEFAULT 0 CHECK (is_default IN (0, 1)),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE UNIQUE INDEX ai_providers_single_default ON ai_providers (is_default) WHERE is_default = 1;

-- Application settings (spec §5.1): one JSON value per key.
CREATE TABLE app_settings (
  setting_key TEXT PRIMARY KEY NOT NULL CHECK (length(setting_key) BETWEEN 1 AND 128),
  setting_value TEXT NOT NULL CHECK (json_valid(setting_value)),
  updated_at INTEGER NOT NULL
) WITHOUT ROWID;
